// Revisa los eventos y hoteles de Comfandi, guarda lo que ya vio y avisa al celular cuando sale algo nuevo.
// Corre sola dos veces al día (Cada día) y también cuando Armoni abre Salidas Ema (Webhook).
const sd = $getWorkflowStaticData('global');
const http = (o) => this.helpers.httpRequest(o);
const AHORA = Date.now();
const FUENTES = [
  { url: 'https://comfandivirtual.com.co/167-eventos-y-actividades', grupo: 'eventos' },
  { url: 'https://comfandivirtual.com.co/1281-hoteles', grupo: 'hoteles' }
];
const NO_QUIERO = /pasad[ií]a/i;   // pasadías no
const PARA_EMA = /ni[ñn]|infantil|kids|familia|beb[eé]|t[ií]teres|did[aá]ctic|musical|teatro|cuento|t[ií]teres|vacacional|recreaci|granja|parque|circo|magia|navide/i;

let esWeb = false;
try { esWeb = !!$('Webhook').first(); } catch (e) {}
if (esWeb) {
  const q = $('Webhook').first().json.query || {};
  if (q.token !== 'mercado-7d41c2a9e05b') return [{ json: { ok: false } }];
}

const limpia = (t) => String(t || '').replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&#0?39;|&apos;/g, "'").replace(/&quot;/g, '"').replace(/\s+/g, ' ').trim();
const absoluta = (u) => !u ? '' : u.startsWith('//') ? 'https:' + u : u.startsWith('/') ? 'https://comfandivirtual.com.co' + u : u;

// PrestaShop devuelve el listado en JSON cuando se le pide como lo hace su propia página
function deJSON(j) {
  const ps = (j && (j.products || (j.listing && j.listing.products))) || [];
  return ps.map(p => ({
    id: String(p.id_product || p.id || p.url),
    nombre: limpia(p.name),
    url: absoluta(p.url || p.link),
    img: absoluta((p.cover && ((p.cover.bySize && (p.cover.bySize.home_default || p.cover.bySize.medium_default)) || p.cover.medium || p.cover.large || {}).url) || ''),
    precio: limpia(p.price || ''),
    detalle: limpia(p.description_short || '').slice(0, 180)
  }));
}
// si no llega JSON, se lee el HTML de las tarjetas de producto
function deHTML(html) {
  const out = [];
  const partes = String(html || '').split(/<article\b/i).slice(1);
  for (const a of partes) {
    if (!/product-miniature|js-product|product_item|product-item/i.test(a.slice(0, 400))) continue;
    const id = (a.match(/data-id-product="(\d+)"/) || [])[1];
    const url = (a.match(/href="(https?:\/\/[^"]+?\.html[^"]*)"/i) || [])[1] || '';
    let nombre = (a.match(/class="[^"]*product-title[^"]*"[^>]*>([\s\S]*?)<\/(?:h\d|div|p)>/i) || [])[1] || (a.match(/\balt="([^"]+)"/i) || [])[1] || '';
    const img = (a.match(/data-full-size-image-url="([^"]+)"/i) || a.match(/data-src="([^"]+)"/i) || a.match(/<img[^>]+src="([^"]+)"/i) || [])[1] || '';
    const precio = (a.match(/class="[^"]*\bprice\b[^"]*"[^>]*>([\s\S]*?)<\/span>/i) || [])[1] || '';
    nombre = limpia(nombre);
    if (!nombre || !url) continue;
    out.push({ id: id || url, nombre, url, img: absoluta(img), precio: limpia(precio), detalle: '' });
  }
  return out;
}

async function leerFuente(f) {
  const todos = [];
  for (let pag = 1; pag <= 4; pag++) {
    const u = f.url + '?page=' + pag;
    let lote = [], total = 1;
    try {
      const r = await http({ url: u + '&from-xhr', headers: { 'Accept': 'application/json, text/javascript, */*; q=0.01', 'X-Requested-With': 'XMLHttpRequest', 'User-Agent': 'Mozilla/5.0 (Armoni)' }, json: true, timeout: 20000 });
      const j = typeof r === 'string' ? JSON.parse(r) : r;
      lote = deJSON(j);
      total = (j && j.pagination && j.pagination.pages_count) || 1;
    } catch (e) {}
    if (!lote.length) {
      const html = await http({ url: u, headers: { 'User-Agent': 'Mozilla/5.0 (Armoni)', 'Accept': 'text/html' }, timeout: 20000 });
      lote = deHTML(html);
      const m = String(html).match(/[?&]page=(\d+)[^"]*"[^>]*>\s*(\d+)\s*</g);
      total = m ? Math.max(1, ...m.map(x => +((x.match(/>\s*(\d+)/) || [])[1] || 1))) : 1;
    }
    lote.forEach(p => { if (!todos.find(x => x.id === p.id)) todos.push(p); });
    if (pag >= total || !lote.length) break;
  }
  return todos.map(p => ({ ...p, grupo: f.grupo }));
}

const hace = (h) => AHORA - h * 3600 * 1000;
const fresco = sd.revisado && sd.revisado > hace(6);
let errores = [];
if (!esWeb || !fresco || !sd.planes) {
  const encontrados = [];
  for (const f of FUENTES) {
    try { encontrados.push(...await leerFuente(f)); }
    catch (e) { errores.push(f.grupo + ': ' + (e.message || 'no se pudo leer')); }
  }
  const sirven = encontrados.filter(p => !NO_QUIERO.test(p.nombre + ' ' + p.url));
  if (sirven.length || !errores.length) {
    const vistos = sd.vistos || {};
    const primeraVez = !sd.revisado;
    const nuevos = [];
    for (const p of sirven) {
      if (!vistos[p.id]) { vistos[p.id] = AHORA; if (!primeraVez) nuevos.push(p); }
      p.desde = vistos[p.id];
      p.paraEma = p.grupo === 'eventos' && PARA_EMA.test(p.nombre + ' ' + p.detalle);
    }
    // olvida lo que ya no está publicado desde hace más de 60 días
    const ids = new Set(sirven.map(p => p.id));
    for (const k of Object.keys(vistos)) if (!ids.has(k) && vistos[k] < hace(24 * 60)) delete vistos[k];
    sd.vistos = vistos; sd.planes = sirven; sd.revisado = AHORA;

    // aviso al celular (solo con lo nuevo y solo una vez por plan)
    if (nuevos.length) {
      const uno = nuevos[0];
      const titulo = nuevos.length === 1 ? (uno.grupo === 'hoteles' ? '🏨 Nuevo plan para ustedes' : (uno.paraEma ? '🎈 Nuevo plan para Ema' : '🎭 Nuevo en Comfandi')) : '✨ ' + nuevos.length + ' planes nuevos en Comfandi';
      const cuerpo = nuevos.length === 1 ? uno.nombre + (uno.precio ? ' · ' + uno.precio : '') : nuevos.slice(0, 3).map(p => p.nombre).join(' · ');
      try { await http({ method: 'POST', url: 'http://localhost:5678/webhook/push-enviar', body: { token: 'mercado-7d41c2a9e05b', title: titulo, body: cuerpo, url: './?ver=ema', tag: 'comfandi' }, json: true, timeout: 15000 }); }
      catch (e) { errores.push('aviso: ' + (e.message || 'no salió')); }
    }
  }
}
sd.errores = errores;
const planes = (sd.planes || []).slice().sort((a, b) => (b.desde || 0) - (a.desde || 0));
return [{ json: { web: esWeb, ok: true, revisado: sd.revisado ? new Date(sd.revisado).toISOString() : null, planes, errores } }];
